        runId: options.runId,
        status: options.status,
        reason: options.reason,
        output: options.output,
        finishedAt,
        sourceType: typeof row?.sourceType === 'string' ? row.sourceType : null,
        sourceId: typeof row?.sourceId === 'string' ? row.sourceId : null,
    };
